# -*- coding: utf-8 -*-
"""大题批次2（33 题：401~421、423~434）：「参考答案」-> 「题目解析 + 标准答案」（代码题附完整代码）。
用法：python D:\\dev-tools\\apply_big_batch.py D:\\dev-tools\\batch_big_2_data.py"""
NEW = {
    401: ("(a) 用 Bresenham 整数算法画线：以误差累积量 err 决定每步走 x、走 y 还是走对角，dx、dy 与方向符号 sx、sy 只由端点差算出，全整数运算、无浮点、各方向通用；(b) 三点求圆心的原理是圆心到三点距离相等，取两条垂直平分线联立：|P-A|²=|P-B|² 展开后消去二次项，得到关于 (cx,cy) 的二元一次方程，两组方程用行列式（克拉默法则）求解，det=0 说明三点共线、无外接圆。复杂度：画线 O(|dx|+|dy|)（两轴步数之和），求圆心 O(1)。易错点：画线漏掉方向符号处理、err 倍率写错（应取 2*err 比较）；求圆心时两组方程结构不统一、共线检测漏写。",
          "两个完整实现如下（(a) Bresenham 画线，(b) 三点求圆心）：\n```c\n#include <stdlib.h>\n\nvoid DrawPixel(int x, int y, int pixColor);   /* 已有画点函数（由环境提供） */\n\n/* (a) Bresenham 整数画线：任意方向、无浮点 */\nvoid DrawLine(int x1, int y1, int x2, int y2, int pixColor) {\n    int dx = abs(x2-x1), sx = x1<x2?1:-1;\n    int dy = -abs(y2-y1), sy = y1<y2?1:-1;\n    int err = dx+dy, e2;\n    while (1) {\n        DrawPixel(x1, y1, pixColor);\n        if (x1==x2 && y1==y2) break;\n        e2 = 2*err;\n        if (e2 >= dy) { err += dy; x1 += sx; }\n        if (e2 <= dx) { err += dx; y1 += sy; }\n    }\n}\n\n/* (b) 求过三点 (x1,y1)(x2,y2)(x3,y3) 的圆心：两条垂直平分线联立求解；\n       返回 0 成功、-1 三点共线（无外接圆） */\nint CircleCenter(double x1, double y1, double x2, double y2,\n                 double x3, double y3, double *cx, double *cy)\n{\n    double a1 = 2 * (x2 - x1), b1 = 2 * (y2 - y1);\n    double c1 = x2 * x2 + y2 * y2 - x1 * x1 - y1 * y1;\n    double a2 = 2 * (x3 - x1), b2 = 2 * (y3 - y1);\n    double c2 = x3 * x3 + y3 * y3 - x1 * x1 - y1 * y1;\n    double det = a1 * b2 - a2 * b1;\n    if (det == 0) return -1;               /* 三点共线：无外接圆 */\n    *cx = (c1 * b2 - c2 * b1) / det;       /* 克拉默法则 */\n    *cy = (a1 * c2 - a2 * c1) / det;\n    return 0;\n}\n```\n要点：(a) 每步三选一（走 x、走 y 或对角），循环 O(|dx|+|dy|) 次、全整数；(b) O(1) 解线性方程组，det 为 0 要报错。"),
    402: ("串转并的关键是「两级寄存」的分工：第一级 8 位移位寄存器在 SerClk 的每个上升沿把 SerIn 逐位移入（{shift_reg[6:0], SerIn} 表示原有低位向高位移、新位进最低位），8 拍收满一个字节；第二级 8 位输出寄存器在 ParClk 上升沿把移位寄存器当前值一次性并行锁存到 ParDataOut。为什么要两级：移位期间移位寄存器内容一直在变，直接输出会出现中间态；加锁存级后输出在整帧期间稳定。时序要求：ParClk 应在 8 拍收满之后给出并满足建立/保持时间。扩展：可加复位/使能，ParDataOut 前再打一拍改善时序。易错点：把 16 个寄存器都写成移位寄存器；漏掉「先收满再锁存」的时序关系。",
          "完整模块如下（第一级 8 位移位 + 第二级 8 位并行锁存，共 16 个 D 触发器）：\n```verilog\nmodule Serial2Parallel (\n    input  wire SerIn, SerClk, ParClk,\n    output wire [7:0] ParDataOut\n);\n    reg [7:0] shift_reg;    /* 第一级：8 位移位寄存器 */\n    reg [7:0] par_reg;      /* 第二级：8 位并行锁存输出寄存器 */\n\n    always @(posedge SerClk)\n        shift_reg <= {shift_reg[6:0], SerIn};   /* 每个 SerClk 逐位移入一位 */\n\n    always @(posedge ParClk)\n        par_reg <= shift_reg;                   /* ParClk 到来时并行锁存 */\n\n    assign ParDataOut = par_reg;\nendmodule\n```\n要点：SerClk 控制逐位移入、ParClk 控制并行锁存；两级结构把「移位过程」与「输出」隔离，避免中间态；ParClk 应在 8 拍收满后给出。"),
    403: ("(a) 内存映射寄存器用宏封装为 (*(volatile unsigned int *)0x20000000)：volatile 告诉编译器该对象可能被硬件随时改变，每次访问都必须真实读写、不得优化或缓存；unsigned int 决定访问宽度为 32 位。(b) 读内存映射寄存器不会被挂起：它是外设寄存器、不是中断源，读回的是引脚回读值或上次写入值（视硬件实现）。(c) 置 bit1 用或运算 |= (1 << 1)，只把 bit1 置 1、其余位不变。(d) SysSetBit 按 HwValue 选择置位/清位，写前先校验位号不大于 15 防移位越界；清位用 &= ~(1 << HwBit)。复杂度 O(1)。易错点：漏 volatile；移位用有符号 1（工程常写 1u）；忘记参数校验；把读寄存器说成「会挂起」。",
          "各小题答案如下（(b) 为说明，(a)(c)(d) 为代码）：\n```c\n/* (a) 定义寄存器变量：宏 + volatile 指针，32 位访问 */\n#define REG_SER_TO_PAR (*(volatile unsigned int *)0x20000000)\n\n/* (b) 读取效果说明：读取不会被挂起——内存映射寄存器读回的是引脚状态（Bit0/1/2 为\n       SerIn/SerClk/ParClk 的回读或上次写入值），不属于异常中断源；\n       具体读回值视硬件实现，可能为最后写入值 */\n\n/* (c) 设置 bit1、保持其余位不变：按位或 */\nvoid set_bit1(void) { REG_SER_TO_PAR |= (1 << 1); }\n\n/* (d) 按 HwValue 置位/清位，其余位不变；先校验位号范围 */\nvoid SysSetBit(unsigned char HwBit, unsigned char HwValue) {\n    if (HwBit > 15) return;                    /* 位号超出有效范围：拒绝 */\n    if (HwValue)\n        REG_SER_TO_PAR |=  (1 << HwBit);       /* 置位 */\n    else\n        REG_SER_TO_PAR &= ~(1 << HwBit);       /* 清位 */\n}\n```\n要点：volatile 保证每次访问真实执行；|=(1<<n) 置位、&=~(1<<n) 清位均不影响其它位；写前校验位号防越界。"),
    404: ("原理：输入 A 上的窄毛刺靠「两级 D 触发器同步打拍 + RC 低通滤波」来纠正。RC 网络对跳变产生充放电斜坡：窄脉冲来不及充到逻辑阈值就被吸收，所以额外脉冲被压窄或移位直至消失；两级触发器在同一时钟下连续采样：第一级可能在跳变附近采到亚稳态，第二级给足一个时钟周期让其衰减稳定，同时把波形对齐到时钟沿。画波形的要点：①所有触发器输出只可能在时钟沿跳变，B 相对 A 延迟一拍、C 相对 B 再延迟一拍（共约两拍）；②B 上被 RC 吸收的窄脉冲对应位置表现为电平不变或宽度变窄的残留；③C 为经过 RC 阈值判定的结果，尖峰被完全滤除，台阶之间是 RC 充电斜坡。延伸考点：亚稳态、建立/保持时间、同步器失效率。易错点：把 B/C 画得与 A 完全同相（漏掉逐级延迟）；忽略 RC 斜坡（把 C 画成理想方波）。",
          "答案（按两级 D 触发器 + RC 延时推导，可照此补划 B、C 点波形）：\n① B 点：输入 A 经一级 D 触发器打拍后的波形——同步到时钟沿、相对 A 延迟一个时钟周期，A 上额外的窄脉冲被压窄或移位（边沿按整拍移动）；\n② C 点：二级打拍 + RC 阈值判定后的输出——相对 B 再延迟一个时钟周期，尖峰脉冲被完全滤除，台阶之间为 RC 充电斜坡（上升/下降沿不平滑）；\n③ 画图自检：B、C 的跳变均只出现在时钟沿上，C 比 B 滞后一拍、B 比 A 滞后一拍，且窄脉冲在 C 上已消失。"),
    405: ("异或法的依据是「一个数异或自己为 0、异或 0 不变」：第一步 m=m^n 后，m 保存了两数所有不同的位；第二步 n=m^n=原m^原n^原n=原m，n 已变成原 m；第三步 m=m^n=原m^原n^原m=原n，完成交换。加减法同理：m=m+n、n=m-n 得原 m、m=m-n 得原 n。要点：①异或法不产生进位、不溢出，适用于整型等可按位异或的类型；②加减法有溢出风险（两数之和超出类型范围时结果错误）；③若两个指针指向同一地址（自交换），异或法会把该地址清零而失效，加判断可规避。复杂度 O(1) 时间、O(1) 空间。易错点：顺序写错；不讨论溢出；把变量含义搞混。",
          "完整程序（异或法，交换后输出验证；加减法给出等价替换行）：\n```c\n#include <stdio.h>\n\nint main(void)\n{\n    int m = 2, n = 3;\n    m = m ^ n;      /* m = 2^3，暂存差异位 */\n    n = m ^ n;      /* n = (2^3)^3 = 2 */\n    m = m ^ n;      /* m = (2^3)^2 = 3 */\n    printf(\"m = %d, n = %d\\n\", m, n);\n    return 0;\n}\n```\n加减法版本（把三行换成 `m = m + n; n = m - n; m = m - n;`，注意两数之和不得超出类型范围）。"),
    406: ("双重循环：外层 i=1~9 表示行（乘号右边较大的数），内层 j=1~i 表示每行式子数——第 i 行恰好 i 个式子，所以输出呈下三角；打印 j*i=积（乘号左边 j、右边 i，与口诀一一、一二的顺序一致）。%-4d 表示左对齐、最小宽度 4 的十进制输出，用于列对齐。总式子数 1+2+…+9=45 个。复杂度 O(9²) 即 O(n²)（这里 n=9 为常数）。易错点：内层边界写成 j<=9（输出矩形而非口诀）；i、j 写反；%-4d 不写导致列参差。",
          "完整程序如下：\n```c\n#include <stdio.h>\n\nint main(void)\n{\n    int i, j;\n    for (i = 1; i <= 9; i++)              /* 第 i 行 */\n    {\n        for (j = 1; j <= i; j++)          /* 每行 j=1..i，共 i 个式子 */\n            printf(\"%d*%d=%-4d\", j, i, i * j);\n        printf(\"\\n\");\n    }\n    return 0;\n}\n```\n要点：内层 j<=i 形成下三角；%-4d 左对齐补齐宽度 4；共 45 个式子。"),
    407: ("内存拷贝按字节复制 n 个字节是基础；工程重点是「重叠」处理：①目标在源后面（d 落在 [s, s+n) 区间内）时从尾到头反序复制，否则前端的复制会覆盖尚未读出的源数据；②其它情况（无重叠或目标在前）从头到尾正序复制。判断条件用地址比较 d > s && d < s + n。返回 dst 以支持链式调用（与标准库 memcpy 一致）。库函数 memcpy 对重叠区间是未定义行为、memmove 才保证重叠安全——本题实现相当于自带 memmove 语义。复杂度 O(n) 时间、O(1) 空间；工程实现常按机器字长批量复制提速。易错点：重叠时方向选错；忘记返回 dst；用错类型指针（必须转成 char 逐字节）。",
          "完整函数（含重叠处理）与调用示例：\n```c\n#include <stddef.h>\n\n/* 拷贝 n 个字节；支持重叠：目标在源后方时从尾到头复制 */\nvoid *my_memcpy(void *dst, const void *src, size_t n)\n{\n    char *d = dst;\n    const char *s = src;\n    if (d > s && d < s + n) {           /* 重叠且目标在后：从尾到头 */\n        d += n;\n        s += n;\n        while (n--) *--d = *--s;\n    } else {                            /* 其它情况：从头到尾 */\n        while (n--) *d++ = *s++;\n    }\n    return dst;                         /* 返回目标首地址 */\n}\n/* 调用示例：my_memcpy(buf + 2, buf, 10); 用法与 memcpy 相同 */\n```\n要点：重叠安全；O(n) 时间、O(1) 空间；返回 dst 支持链式调用。"),
    408: ("三种遍历的命名由「根」的位置决定：前序=根→左→右，中序=左→根→右，后序=左→右→根。已知树：根 A；A 的左子树以 B 为根，B 的左右孩子为 D、E（均为叶子）；A 的右子树只有一个节点 C。推导：前序先写根 A，再递归左子树（B→D→E），最后右子树 C，得 A→B→D→E→C；中序先递归左子树（D→B→E），再根 A，最后 C，得 D→B→E→A→C；后序先左子树（D→E→B），再 C，最后根 A，得 D→E→B→C→A。也可用「前序定根、中序分左右」的还原法验证。复杂度 O(n)。易错点：中序与后序混淆（记住命名看根的位置）；漏掉右子树 C；把 D、E 顺序写反。",
          "按裁剪图（根 A，左子树 B（孩子 D、E），右子树 C（单节点））：\n① 前序（根→左→右）：A→B→D→E→C\n② 中序（左→根→右）：D→B→E→A→C\n③ 后序（左→右→根）：D→E→B→C→A"),
    409: ("冒泡排序的核心思想：每轮从头相邻比较，逆序就交换，每轮至少把当前未排序部分的最大元素「冒」到末尾。①为什么外层 n-1 轮：每轮确定一个元素的最终位置，n 个元素只需 n-1 轮（最后剩的最小元素自然就位）；②为什么内层 n-1-i：经过 i 轮后末尾已有 i 个元素排好，剩下 n-i 个元素只需 n-i-1 次相邻比较；③复杂度：比较次数 (n-1)+(n-2)+…+1=n(n-1)/2，最坏/平均时间 O(n²)、空间 O(1)（原地）；④稳定性：只在严格大于时才交换，相等元素相对次序不变，是稳定排序；⑤swapped 优化：某轮一次交换都没发生说明已有序，立即结束，最好情况（本来有序）只需 1 轮 n-1 次比较、即 O(n)；⑥改成从大到小只需把大于号换成小于号。易错点：内层边界写成 n-1（num[j+1] 越界）或 n（多余比较）；n-1-i 写错；忽略 n=0/1 时循环不动自然正确。延伸：数据量大应改用 qsort/快速排序，冒泡适合教学与小规模近似有序数据。",
          "完整程序如下（含交换优化）：\n```c\n#include <stdio.h>\n#define N 10               /* 数组大小可自行修改 */\n\nvoid bubble_sort(int num[], int n)\n{\n    int i, j, t;\n    int swapped;           /* 优化：若某轮没有交换说明已有序，可提前结束 */\n    for (i = 0; i < n - 1; i++) {              /* 控制比较轮数 */\n        swapped = 0;\n        for (j = 0; j < n - 1 - i; j++) {      /* 每轮比较次数递减（-i 因为末尾已排好） */\n            if (num[j] > num[j + 1]) {         /* 大的往后冒 → 从小到大 */\n                t = num[j + 1];\n                num[j + 1] = num[j];\n                num[j] = t;\n                swapped = 1;\n            }\n        }\n        if (!swapped) break;                   /* 已完全有序 */\n    }\n}\n\nint main(void)\n{\n    int a[N], n, i;\n    printf(\"请输入需要排序的数的个数: \\n\");\n    scanf(\"%d\", &n);\n    printf(\"请依次输入要排序的数: \\n\");\n    for (i = 0; i < n; i++) scanf(\"%d\", &a[i]);\n    bubble_sort(a, n);\n    printf(\"从小到大的排序为: \\n\");\n    for (i = 0; i < n; i++) printf(\"%d \", a[i]);\n    printf(\"\\n\");\n    return 0;\n}\n```\n要点：①两层循环——外层控制轮数（n-1 轮），内层控制每轮比较次数（n-1-i，因每轮结束末尾 i 个元素已就位）；②相邻比较、逆序则交换，使较大元素逐步冒到末尾；③时间复杂度 O(n²)（用 swapped 优化后最好情况 O(n)），空间 O(1)，稳定排序（只在严格大于时交换）；④若要从大到小只需把大于号改成小于号；⑤数据量大时应换用 qsort/快排。"),
    410: ("两个宏考查预处理技巧：①#func 把宏参数变成字符串字面量（字符串化运算符 # 只在宏体中有效）；②args... 与 ##args 是 GNU 可变参数宏扩展（C99 标准写法为 ... 与 __VA_ARGS__）：把可变实参原样传给内部 printf，## 用于实参为空时去掉前面的逗号；③__LINE__、__FILE__ 是预定义宏，编译期展开为当前行号与源文件名；④相邻的字符串字面量会在编译期自动拼接，所以格式串由多段拼成；⑤工程上宏体建议用 do { } while (0) 包裹，避免 if/else 悬挂语句展开错误；宏无类型检查。用途：EPRINTF 统一错误/日志输出（含时间、位置、调用描述），WHEN 条件成立时打印并执行动作。易错点：# 只能对宏参数使用；忘记可变参数省略号；续行符丢失。",
          "宏定义如下（配套的 get_local_time 返回时间字符串）：\n```c\n/* EPRINTF：打印「时间 [行号@文件名]: 调用表达式, 格式化内容」 */\n#define EPRINTF(func, fmt, args...) \\\n    { printf(\"%s [%d @ %s]: \" #func \", \" fmt, \\\n             get_local_time(), __LINE__, __FILE__, ##args); }\n\n/* WHEN：条件成立时打印并执行 act */\n#define WHEN(func, act) \\\n    { if (func) { printf(\"%s [%d @ %s]: \" #func \", \" #act \"\\n\", \\\n        get_local_time(), __LINE__, __FILE__); act; } }\n```\n要点：#func 字符串化、##args 拼接可变参数（GNU 扩展，C99 为 __VA_ARGS__）、__LINE__/__FILE__ 定位；工程上宏体常改用 do { } while (0) 包裹。"),
    411: ("结构体成员可以是函数指针：定义形式为「返回类型 (*成员名)(参数类型表)」，int (*add)(int, int) 读作「add 是一个指针，指向 (int,int)->int 的函数」。初始化时直接写函数名（函数名即函数地址）；调用 ops.add(3,4) 与 (*ops.add)(3,4) 等价。用途：C 中模拟面向对象——把一组操作聚合成「操作集/接口表」，运行时按需替换实现（多态/回调/插件）；驱动框架（如 file_operations）、命令表都基于这种结构。扩展：先 typedef 函数指针类型再在结构体中使用更清晰；结构体使用前要初始化，未初始化指针调用是未定义行为。易错点：定义漏括号（int *add(int,int) 变成返回指针的函数声明）；---与 . 用错（结构体变量用点、指针用箭头）。",
          "完整程序如下：\n```c\n#include <stdio.h>\n\n/* 带函数指针成员的结构体：二元运算操作集 */\ntypedef struct {\n    int (*add)(int, int);      /* 函数指针成员：指向加法函数 */\n    int (*sub)(int, int);      /* 函数指针成员：指向减法函数 */\n} CalcOps;\n\nint add(int a, int b) { return a + b; }\nint sub(int a, int b) { return a - b; }\n\nint main(void)\n{\n    CalcOps ops = { add, sub };        /* 用函数名初始化函数指针 */\n    printf(\"%d\\n\", ops.add(3, 4));     /* 7 */\n    printf(\"%d\\n\", ops.sub(3, 4));     /* -1 */\n    return 0;\n}\n```\n要点：函数指针成员定义要加括号；函数名即地址；ops.add(...) 与 (*ops.add)(...) 等价。"),
    412: ("UML 关系：HardDisk（硬盘）1——*（组合）Partition（分区）；Partition 1——*（组合）Directory（根目录）；Directory 自关联 parent-children（目录可含子目录与文件，一对多）；File（文件）与 Directory 都继承自公共基类 FsNode（文件系统节点），实现统一的多态接口。类代码要点：基类必须有虚析构（用 FsNode 指针删除派生对象时才能正确调用派生类析构）；组合关系用实心菱形、聚合用空心菱形，画图时要说明选择。复杂度：遍历目录树 O(n)。易错点：漏掉自关联（目录的子目录）；File/Directory 不写共同基类；忘记虚析构。",
          "UML 类图（可照着画）：HardDisk 1——* Partition；Partition 1——* Directory；Directory 1——* File/Directory（自关联，表示「目录包含文件与子目录」）；File 与 Directory 均继承公共基类 FsNode（继承用空心三角箭头、组合用实心菱形）。\n类代码如下（C++ 示意）：\n```cpp\n#include <vector>\n#include <string>\n\n/* 文件系统节点基类：统一接口多态；虚析构保证经基类指针删除安全 */\nclass FsNode {\npublic:\n    virtual ~FsNode() {}\n    virtual std::string name() const = 0;\n};\n\nclass File : public FsNode {          /* 文件：叶子节点 */\n    std::string m_name;\n    unsigned long m_size;\npublic:\n    std::string name() const override { return m_name; }\n    void setName(const std::string &n) { m_name = n; }\n};\n\nclass Directory : public FsNode {     /* 目录：容器，自关联包含子项 */\n    std::string m_name;\n    std::vector<FsNode *> m_children;\npublic:\n    std::string name() const override { return m_name; }\n    void add(FsNode *node) { m_children.push_back(node); }\n};\n\nclass Partition {                     /* 分区：拥有一个根目录 */\npublic:\n    Directory root;\n};\n\nclass HardDisk {                      /* 硬盘：拥有多个分区 */\npublic:\n    std::vector<Partition> parts;\n};\n```\n要点：硬盘-分区-目录为组合关系；Directory 自关联包含子目录与文件；统一基类多态遍历。"),
    413: ("交易处理模型 =「接收-分发-处理-应答」的经典架构：①服务器从 TCP 连接收报文，从报文头解析出交易码；②用注册表把交易码映射到对应交易处理对象（map 或数组）；③多态调用该对象的 parse/process，返回结果写回连接。为什么用抽象基类+虚函数：新增交易只新增子类并注册，分发代码不改（开闭原则）；表驱动分发避免巨型 switch。工程要点：报文要有长度字段做边界检查（防越界）；处理失败返回错误码；注册表通常启动时集中注册；C 语言可用函数指针表实现同样分发。复杂度：分发查找 O(log n)（map）或 O(1)（数组索引），处理时间由具体交易决定。易错点：不做边界检查直接解析；分发写成难维护的 if-else 链；忘记虚析构。",
          "核心结构（抽象交易类 + 注册表 + 服务器循环）如下：\n```cpp\n#include <map>\n#include <cstddef>\n\n/* 抽象交易处理类：所有交易处理器的公共接口 */\nclass Transaction {\npublic:\n    virtual ~Transaction() {}\n    virtual int parse(const char *msg, int len) = 0;    /* 解析报文 */\n    virtual int process(char *resp, int &rlen) = 0;     /* 处理并生成应答 */\n    virtual int type() const = 0;                       /* 交易码 */\n};\n\n/* 交易注册表：交易码 -> 处理类对象 */\nclass TxRegistry {\n    std::map<int, Transaction *> table;\npublic:\n    void reg(Transaction *t) { table[t->type()] = t; }\n    Transaction *find(int code) {\n        auto it = table.find(code);\n        return it == table.end() ? nullptr : it->second;   /* 未注册返回空 */\n    }\n};\n\n/* 服务器主循环（伪代码）：\n   socket recv -> 校验长度 -> 读交易码 code -> find(code)\n   -> parse(msg,len) -> process(resp,rlen) -> socket send；失败回错误码 */\n```\n要点：多态分发 + 注册表解耦——新增交易只加子类并 reg；未注册交易码返回错误；解析前必须校验长度。"),
    414: ("思路：求「同一号码相邻两次通话的间隔」。①按主叫号码分组（PARTITION BY 主叫号码）、按通话起始时间排序（ORDER BY 通话起始时间）；②用窗口函数 LEAD 取「下一通电话的起始时间」，与本通的结束时间相减即两次通话之间的空闲间隔；③TIMESTAMPDIFF(SECOND, 结束, 下一开始) 返回秒数差；④外层过滤 gap > 10 即间隔大于 10 秒；⑤最后一通没有下一通，LEAD 返回 NULL，被 WHERE 自动过滤。自连接替代写法：用相关子查询 MIN(下一通开始时间) 再减，语义相同但性能差。复杂度：排序 O(n log n)。易错点：用起始减起始还是结束减起始要按「间隔」的语义；漏 PARTITION 会把不同号码混在一起；NULL 行处理。",
          "窗口函数解法（MySQL 8.0）：\n```sql\nSELECT ID FROM (\n    SELECT ID,\n           TIMESTAMPDIFF(SECOND, 通话结束时间,\n               LEAD(通话起始时间) OVER (\n                   PARTITION BY 主叫号码 ORDER BY 通话起始时间)) AS gap\n    FROM calls\n) t\nWHERE gap > 10;\n```\n要点：LEAD 取同号码下一通的起始时间；gap = 本通结束到下一通开始的秒数；最后一通 gap 为 NULL 被过滤。（答案样例：6、7、8、9、10 条记录符合）"),
    415: ("脚本思路：遍历目录下每个条目（\"$1\" 通配展开）；basename 取出纯文件名；tr 'A-Z' 'a-z' 把大写字母映射为小写；mv 把原路径重命名为「目录/小写名」。要点：①变量与通配符要用双引号包住，防文件名含空格被分词；②已是小写的文件名会「自己 mv 到自己」，可加判断避免多余报错；③只处理一层目录，子目录内部需用 find 递归；④重命名冲突（两个名字只差大小写）时要留意。复杂度 O(条目数)。易错点：漏引号；tr 参数方向写反；mv 目标漏目录前缀。",
          "完整脚本（将指定目录下所有文件名改为小写）：\n```sh\n#!/bin/bash\n# 用法: ./to_lower.sh 目录路径\nfor f in \"$1\"/*; do\n    n=$(basename \"$f\")                          # 取文件名\n    mv \"$f\" \"$1/$(echo \"$n\" | tr 'A-Z' 'a-z')\"   # 大写映射为小写后重命名\ndone\n```\n要点：双引号防空格分词；tr 'A-Z' 'a-z' 完成大小写映射；如需递归子目录可改用 find 配合本段逻辑。"),
    416: ("原代码的错误是「值传递」：形参 p 只是实参的副本，函数里 malloc 的结果赋给副本，调用者 str 仍为 NULL，后续 strcpy/printf 直接崩溃。修法（保持两个函数结构）：GetMemory 改为接收二级指针 char * *p，调用处传 &str，函数内 *p = malloc(...) 把分配结果写回调用者；同时补三处健壮性：①malloc 判空（失败不能用）；②printf(str) 改为 printf(\"%s\", str)（内容含 % 会被当格式串）；③用完 free(str) 防泄漏。另一等价方案是让 GetMemory 直接返回分配的指针。易错点：只改函数体不传地址（依然错）；malloc 不判空；忘记 free；返回局部数组指针（悬空）。",
          "修改后的完整代码（其二：返回值方案亦可）：\n```c\n#include <stdlib.h>\n#include <string.h>\n#include <stdio.h>\n\n/* 改为二级指针：把 malloc 的地址写回调用者 */\nvoid GetMemory(char * *p, unsigned int size)\n{\n    *p = (char *)malloc(size);\n    if (*p == NULL) { /* 错误处理 */ }\n}\n\nint main(void)\n{\n    char *str = NULL;\n    GetMemory(&str, 100);          /* 传 str 的地址，函数才能修改 str */\n    if (str) {\n        strcpy(str, \"Anyka is a hi-tech company.\");\n        printf(\"%s\", str);         /* 不用 printf(str)，避免格式串问题 */\n        free(str);                 /* 释放动态内存 */\n        str = NULL;\n    }\n    return 0;\n}\n```\n说明：值传递改成传二级指针是本题关键；配套做到 malloc 判空、printf(\"%s\")、free 释放。也可改为 char *GetMemory(unsigned int size) 返回指针的方案。"),
    417: ("实现要点：①逐字符拷贝直到源串的 '\\0'——赋值表达式先执行（'\\0' 也被拷进目标，保证目标串结尾正确），再判断本次拷入的是否为 '\\0'；②返回目标首地址（与标准库语义一致，支持链式调用）；③形参 const char * 表示承诺不修改源串。为什么不能漏拷 '\\0'：目标串就不是合法字符串了。工程注意：本函数不检查目标缓冲区大小，目标不够会溢出（实际用 strncpy/snprintf 或先算长度）；源和目标重叠时行为未定义（需 memmove）。复杂度 O(n) 时间、O(1) 空间。易错点：判断条件写错导致漏拷或越界；忘记返回 dest；无长度检查导致溢出；const 漏写。",
          "完整实现与调用示例：\n```c\n/* 将 strSrc 拷贝到 strDest（含结尾 '\\0'），返回 strDest 首地址 */\nchar *strcpy(char *strDest, const char *strSrc)\n{\n    char *p = strDest;                      /* 保存目标首地址用于返回 */\n    while ((*p++ = *strSrc++) != '\\0')      /* 逐字符拷贝，'\\0' 也拷入并终止 */\n        ;\n    return strDest;\n}\n/* 调用示例：char dst[32]; strcpy(dst, \"hello\"); */\n```\n要点：逐字符拷贝含 '\\0'；返回目标首地址；const 修饰源串承诺只读。"),
    418: ("把新节点插到 p 之后、且不增加变量，关键是顺序：①先让新节点的 next 指向 p 的后继（先接）——利用旧值；②再让 p 的 next 指向新节点（后断）。如果颠倒（先改 p->next），p 原来的后继链就丢了，无法再找到它。这利用了「写入前先利用旧值」的技巧，不需要额外临时变量。复杂度 O(1)。易错点：两句顺序写反；前提是 p 为非空节点（题干已给）。延伸：若允许增加变量，也可 q = p->next; p->next = pTmp; pTmp->next = q;。",
          "两行代码（顺序不能反，先接后断）：\n```c\npTmp->next = p->next;    /* ① 先让新节点接上 p 的后继 */\np->next = pTmp;          /* ② 再让 p 指向新节点 */\n```\n要点：不增加变量靠「先接后断」；顺序颠倒会丢失 p 的原后继链；单链表插入 O(1)。"),
    419: ("三极管（BJT）三种工作区由两个 PN 结偏置决定：①截止区——发射结反偏/无基极电流，IC 约 0，相当于断开的开关；②放大区——发射结正偏、集电结反偏，IC=β·IB，用于信号放大；③饱和区——两结都正偏，VCE 很低（约 0.3V），相当于闭合的开关。放大用法（共射电路）：基极经偏置电阻/分压获得静态工作点，输入小信号经耦合电容加到基极，集电极经负载电阻接电源、输出反相放大信号；开关用法：基极经限流电阻接控制信号（MCU IO），集电极串负载（LED/继电器）接电源，低电平截止、高电平饱和导通；继电器必须并联续流二极管保护。易错点：放大/开关的偏置条件说混；开关电路漏基极限流电阻；感性负载漏续流二极管。",
          "三极管两种典型用法（配图要点，可照着画）：\n① 放大用法（共射放大电路）：VCC 经集电极负载电阻 RC 接集电极；基极经偏置电阻 RB（或分压偏置）获得静态工作点；输入小信号经耦合电容加到基极；发射极接地；输出从集电极取出，与输入反相、幅度放大。偏置条件：发射结正偏、集电结反偏（IC=β·IB）。\n② 开关用法：控制信号经基极限流电阻 RB 接基极；发射极接地；集电极经负载（LED 串限流电阻，或继电器线圈）接 VCC；控制高电平时饱和导通、低电平时截止。偏置条件：饱和=两结正偏（VCE 约 0.3V）；截止=发射结反偏。感性负载（继电器）要并联续流二极管。\n标注要素：两种电路的电源、电阻、负载、输入/输出位置与上述偏置条件。"),
    420: ("①时钟电路：单片机一般用石英晶振接 XTAL1/XTAL2（内部反相放大器+晶振+负载电容构成皮尔斯振荡器），两个负载电容（典型 20~33pF）分别从晶振两端接地，保证稳定起振并微调频率；无源晶振需要这两个电容。②复位电路：上电复位用 RC——电阻一端接 VCC、电容一端接地，复位脚接 RC 节点；上电瞬间电容未充电、复位脚为有效电平，随充电降到阈值以下释放复位，复位时间约 RC 时间常数；可并联按钮做手动复位。典型值 R=10K、C=10uF。延伸：51 系列为高电平复位；STM32 为低电平复位（NRST 内部上拉、外部接 100nF 到地）。易错点：电容未接地；复位电平极性记反；复位时间不足（电容太小）。",
          "两个电路（配图要点，可照着画）：\n① 时钟电路：石英晶振跨接单片机 XTAL1、XTAL2 两脚；晶振两端各接一个负载电容（典型 20~30pF）到地；与芯片内部振荡电路配合起振，提供主时钟。\n② 复位电路（上电复位）：电阻 R 一端接 VCC、另一端接复位脚；电容 C 接在复位脚与地之间（复位脚即 RC 节点）；上电时电容充电，复位脚维持有效电平约 RC 时长后释放；复位按钮并联在电容两端（按下即手动复位）。典型值 R=10K、C=10uF（时间常数约 0.1s）。\n标注要素：晶振+两负载电容+XTAL1/XTAL2；R 接 VCC、C 接地、复位脚接 RC 节点、按钮并联在 C 上（51 系列为高电平复位）。"),
    421: ("①单例（Singleton）：保证一个类只有一个实例并提供全局访问点——私有构造、静态方法返回唯一实例；推荐 Meyers 写法（函数内 static 局部变量，C++11 起初始化线程安全），并删除拷贝构造与赋值运算符。②工厂方法：定义创建对象的接口，让子类决定实例化哪个类。③观察者：对象状态变化时自动通知所有依赖它的观察者（发布-订阅）。④策略：定义一系列算法并分别封装，使它们可以互相替换。⑤适配器：把一个类的接口转换成客户期望的另一个接口。按创建型/结构型/行为型分类记忆。易错点：单例每次 new（不是单例）；不禁止拷贝导致能复制出第二个实例；线程安全说明（C++11 局部 static 线程安全）。",
          "常用设计模式（各一句话定义）：①单例——保证一个类仅有一个实例，并提供全局访问点；②工厂方法——定义创建对象的接口，让子类决定实例化哪个类；③观察者——对象状态变化时自动通知依赖它的观察者；④策略——定义算法族并分别封装，使它们可以互相替换；⑤适配器——把不兼容的接口转换成客户期望的接口。\n单例示范（C++11 线程安全写法）：\n```cpp\nclass Singleton {\npublic:\n    static Singleton &getInstance() {\n        static Singleton inst;      /* C++11 起：局部静态变量初始化线程安全 */\n        return inst;\n    }\n    Singleton(const Singleton &) = delete;             /* 禁止拷贝 */\n    Singleton &operator=(const Singleton &) = delete;  /* 禁止赋值 */\nprivate:\n    Singleton() {}                                     /* 私有构造 */\n};\n```\n要点：私有构造、静态实例、删除拷贝与赋值；C++11 起局部 static 初始化线程安全。"),
    423: ("String 类四个特殊成员函数的考查点全在「资源管理」：①通用构造：判空指针（NULL 时也分配 1 字节存 '\\0'，保证对象可用）；分配 strlen+1 字节并拷贝。②拷贝构造：深拷贝——为新对象独立分配内存再复制内容（浅拷贝只复制指针，两个对象析构时双重释放）。③析构：delete[] 释放（new[]/delete[] 必须配对）。④赋值运算符：先自赋值检查（this != &rhs，否则先 delete 会把 rhs 数据销毁）；再释放旧内存、分配新内存、拷贝；返回 *this 支持连续赋值。异常安全改进（延伸）：先 new 成功再 delete 旧内存，或拷贝-交换惯用法。易错点：深/浅拷贝混用；漏自赋值判断；delete 与 delete[] 混用；返回值忘记引用。",
          "配套类声明与四个成员函数实现（深拷贝、自赋值检查、释放旧内存）：\n```cpp\n#include <cstring>\n\nclass String {\npublic:\n    String(const char *str = nullptr);\n    String(const String &other);\n    ~String();\n    String &operator=(const String &rhs);\nprivate:\n    char *m_data;\n};\n\nString::String(const char *str) {\n    if (!str) {                        /* 空指针：分配 1 字节存 '\\0' */\n        m_data = new char[1];\n        m_data[0] = '\\0';\n    } else {\n        m_data = new char[strlen(str) + 1];\n        strcpy(m_data, str);\n    }\n}\nString::String(const String &other) {  /* 拷贝构造：深拷贝 */\n    m_data = new char[strlen(other.m_data) + 1];\n    strcpy(m_data, other.m_data);\n}\nString::~String() { delete [] m_data; } /* 析构：配对释放 */\n\nString &String::operator=(const String &rhs) {\n    if (this != &rhs) {                 /* 自赋值检查 */\n        delete [] m_data;               /* 释放旧内存 */\n        m_data = new char[strlen(rhs.m_data) + 1];\n        strcpy(m_data, rhs.m_data);\n    }\n    return *this;                       /* 返回引用支持连续赋值 */\n}\n```\n要点：深拷贝防双重释放；自赋值检查；先释放再分配；返回 *this。"),
    424: ("本题是架构设计题，两个模式配合：①状态模式（State）——把生命状态（精神饱满/正常/疲倦/危险/死亡）封装成独立类，每个状态定义进入/持续行为；角色（上下文）持有当前状态对象，切换委托给状态对象，避免遍地 if/switch；与策略模式的区别：状态类之间知道彼此、可触发转移，而策略由外部选择、互相独立。②观察者模式（Observer）——角色作为主题（Subject）维护观察者列表（UI 血条颜色、音效、成就等），状态变化时广播通知，观察者与角色解耦、可动态订阅。顶层设计：Role（上下文）持 LifeState 与观察者列表；LifeState 定义接口（onEnter/name）；具体状态类实现行为与转移条件（按生命值阈值）；UI 等实现 LifeObserver；可再引入事件总线解耦模块。易错点：状态类间硬编码互相耦合；遍历观察者列表时增删（迭代器失效）；死亡状态未屏蔽其它转移。",
          "架构设计要点（可照着画类图）：\n① 状态模式：抽象状态 LifeState（接口 onEnter/name）；具体状态类——Energetic（精神饱满）、Normal（正常）、Tired（疲倦）、Danger（危险）、Dead（死亡），各自实现进入行为（UI 颜色、可行动性等），并按生命值阈值触发状态转移。\n② 观察者模式：观察者接口 LifeObserver（onStateChanged）；Role 作为 Subject 维护观察者列表（attach/detach），状态切换时 notify 全体（UI、音效、成就等订阅方）。\n顶层结构：Role（角色上下文：生命值 + 当前状态 + 观察者列表）→ setState 委托状态对象并广播通知；UI 模块实现 LifeObserver 更新显示。关键类骨架：\n```cpp\n#include <vector>\n\n/* 状态接口：每种生命状态实现自己的行为与转移条件 */\nclass LifeState {\npublic:\n    virtual ~LifeState() {}\n    virtual void onEnter(class Role *role) = 0;\n    virtual const char *name() const = 0;\n};\n\n/* 观察者接口：UI/音效/成就等实现 */\nclass LifeObserver {\npublic:\n    virtual ~LifeObserver() {}\n    virtual void onStateChanged(class Role *role, const char *state) = 0;\n};\n\n/* 上下文：角色持有当前状态与观察者列表，切换状态时通知观察者 */\nclass Role {\n    LifeState *m_state = nullptr;\n    std::vector<LifeObserver *> m_obs;\npublic:\n    void attach(LifeObserver *o) { m_obs.push_back(o); }\n    void setState(LifeState *s) {\n        m_state = s;\n        if (m_state) {\n            m_state->onEnter(this);\n            for (auto o : m_obs) o->onStateChanged(this, m_state->name());\n        }\n    }\n};\n```\n说明：状态类之间按生命值阈值转移（如低于下限进入 Danger）；UI 等通过实现 LifeObserver 订阅变化；两模式组合使状态逻辑与显示逻辑解耦。"),
    425: ("哈希去重思路：用 256 大小的标记数组（桶）记录每个字符是否出现过（字符值当索引，O(1) 查重）；再用双指针原地重写——r 指针从头读、w 指针指向下一个可写位置，遇没出现过的字符就标记并写入、w 前移；扫完后在 w 处补 '\\0'。因为去重只让字符串变短（w 永不超前于 r），在原串上覆盖写是安全的、不需要额外缓冲区。复杂度 O(n) 时间、O(256)=O(1) 额外空间。易错点：忘记补结尾 '\\0'；用 char 索引时负数问题（转成 unsigned char）；丢失「保留首次出现顺序」；大小写区分（'a' 与 'A' 是不同字符）。延伸：若要求去重后字典序最小需单调栈类解法；限长 ≤10000 说明可开 10001 的输入缓冲。",
          "完整程序（哈希标记 + 双指针原地去重，O(n)）：\n```c\n#include <stdio.h>\n\n/* 原地去除重复字符：每个字符只保留第一次出现，其余删除 */\nvoid dedup(char *s)\n{\n    int seen[256] = {0};        /* 桶标记：字符是否已出现过 */\n    char *w = s;                /* 写指针 */\n    for (char *r = s; *r; r++) {/* 读指针 */\n        unsigned char c = (unsigned char)*r;\n        if (!seen[c]) {\n            seen[c] = 1;\n            *w++ = c;           /* 首次出现：写入并前移 */\n        }\n    }\n    *w = '\\0';                  /* 补上新的结尾 */\n}\n\nint main(void)\n{\n    char buf[10001];            /* 题目限长 ≤10000 */\n    printf(\"请输入字符串: \");\n    if (scanf(\"%10000s\", buf) != 1) return 1;\n    dedup(buf);\n    printf(\"%s\\n\", buf);        /* 例: abcaadc -> abcd */\n    return 0;\n}\n```\n要点：seen[256] 标记 + 双指针原地重写；O(n) 时间、O(1) 额外空间（仅 256 桶）；结果保持首次出现的顺序。"),
    426: ("换算思路：从 2000-01-01 00:00:00 起把秒数逐级扣减：先按一整年的秒数（平年 365×86400、闰年 366×86400）循环扣，扣到不足一年确定年份；再按一整月的秒数（各月天数×86400，2 月按闰年规则取 29 或 28）扣到不足一月确定月份；剩余 sec/86400 + 1 即日期（日期从 1 起算所以要 +1）；再依次除 3600、60 得时、分、秒。闰年判断：2000~2099 范围内 %4==0 即闰年（跨世纪需 %100/%400：2000 是闰年、2100 不是）。复杂度 O(年数+月数)（常数上限约 100）。易错点：day 忘记 +1；2 月闰年 29 天漏处理；小时/分/秒余数链写错；大秒数用 int 溢出（用 unsigned）。延伸：标准库可用 time_t + gmtime/localtime。",
          "完整程序（DWORD 秒数自 2000-01-01 0:0:0 起转日期时间字符串）：\n```c\n#include <stdio.h>\n\n/* 把自 2000-01-01 0:0:0 起的 DWORD 秒数转换为日期时间并打印 */\nvoid sec2time(unsigned int sec)\n{\n    static const int mdays[] = {31,28,31,30,31,30,31,31,30,31,30,31};\n    int year = 2000, month = 1, day, hour, min, sec2p;\n\n    while (1) {                              /* 逐年扣，确定年份 */\n        int ydays = (year % 4 == 0) ? 366 : 365;\n        if (sec >= ydays * 86400u) { sec -= ydays * 86400u; year++; }\n        else break;\n    }\n    while (1) {                              /* 逐月扣，确定月份 */\n        int m = mdays[month - 1];\n        if (month == 2 && year % 4 == 0) m = 29;   /* 闰年 2 月 29 天 */\n        if (sec >= m * 86400u) { sec -= m * 86400u; month++; }\n        else break;\n    }\n    day  = sec / 86400 + 1;  sec %= 86400;   /* 日期从 1 起算 */\n    hour = sec / 3600;       sec %= 3600;\n    min  = sec / 60;         sec2p = sec % 60;\n    printf(\"%d年%02d月%02d日 %02d时%02d分%02d秒\\n\",\n           year, month, day, hour, min, sec2p);\n}\n\nint main(void)\n{\n    unsigned int sec;\n    printf(\"请输入 DWORD 秒数（自 2000-01-01 0:0:0 起）: \");\n    if (scanf(\"%u\", &sec) != 1) return 1;\n    sec2time(sec);\n    return 0;\n}\n```\n要点：逐年→逐月→逐级除；2 月闰年处理；日期从 1 起算要 +1。"),
    427: ("目标流程：读键盘事件→判断按下→点亮键盘灯→延时 2 秒→关灯→循环。Linux 下按键与其它输入事件统一走输入子系统（/dev/input/eventX），事件用 struct input_event 描述（type=EV_KEY、code=键码、value=1 按下/0 抬起）；键盘 LED 通过 EV_LED 事件（如 LED_KBD）或 ioctl 控制；主循环阻塞 read 拿事件，收到「按下」后点亮 LED、延时 2 秒再关闭。注意点：sleep(2) 会阻塞整个线程——简单场景可用；若还要及时响应其它事件，应改用定时器/select 超时，避免延时期间漏事件；Wince 对应使用键盘驱动事件 + 定时回调（伪码同构）。易错点：不区分按下/抬起（重复触发）；在事件回调里直接 sleep 卡住消息循环；忘记区分不同键盘设备。考点：设备打开、事件结构、LED 控制、延时方式。",
          "伪码如下（Linux 思路，Wince 同构）：\n```\n打开键盘设备（/dev/input/eventX 或键盘驱动句柄）\nwhile (1):\n    阻塞读取按键事件\n    if 按下事件:\n        ioctl(设备, SET_LED, ON)    // 点亮键盘灯\n        sleep(2) 或定时器 2 秒      // 延迟 2 秒\n        ioctl(设备, SET_LED, OFF)   // 关闭键盘灯\n```\n要点：读事件区分按下/抬起；点亮后延时 2 秒再关灯；阻塞 sleep 简单场景可用，多任务下建议改用定时器/select 超时避免卡住事件循环。"),
    428: ("关键点：串口是字节流，没有天然的消息边界，必须自定义协议定界+校验。①帧格式：帧头（固定同步字，用来找帧起点）+ 长度（数据区字节数）+ 命令/类型 + 数据 + 校验（CRC16/和校验）+ 帧尾（可选）；长度字段让接收方知道本帧有多少字节、校验保证数据完整。②空闲中断（IDLE）判定帧边界：一帧发完后总线空闲超过一个字节传输时间，STM32 的 USART 产生 IDLE 标志/中断，此时把本次收到的字节从环形缓冲取出即得完整一帧（不消耗定时器、也不会把两帧粘在一起）。③接收流程：RX 中断（或 DMA）只管把字节塞进环形缓冲；IDLE 中断里取走整帧交给解析任务（中断里不做耗时解析）；校验帧头→长度合法性→CRC：通过则解析/应答，失败丢弃并重同步。工程要点：缓冲足够大防溢出丢帧；长度字段做上限校验；断帧由空闲超时或校验失败处理。易错点：在中断里做耗时解析、不做长度/CRC 校验、粘包/断帧处理缺失。",
          "① 协议帧格式（稳健设计）：\n帧头（2B 固定同步字）+ 长度（数据区字节数）+ 命令/类型（1B）+ 数据（变长）+ 校验（CRC16 或和校验）+ 帧尾（可选）。\n② 空闲中断收帧解析流程（可照着画流程图）：\n① 初始化：使能 USART RX 中断/DMA 与总线空闲（IDLE）中断，准备环形缓冲区；\n② 每收到 1 字节：中断/DMA 存入环形缓冲区（只收不解析）；\n③ 总线空闲：IDLE 中断触发，取走本次一帧的全部字节（空闲标志=帧结束）；\n④ 校验：帧头是否正确→长度是否在合法范围→CRC 是否通过；\n⑤ 通过：投递解析/组包应答（在主循环或任务中完成）；\n⑥ 失败：丢弃本帧，从缓冲区数据中找下一帧头重同步。"),
    429: ("不借助字符串库函数的数字法：①负数（含负号）约定不是回文数，直接返回 0；②把整数逐位反转：rev = rev*10 + x%10（取最低位拼到结果末尾），x /= 10，循环到 x 为 0；③比较 rev 与原始值相等即为回文。例子：12321 反转仍 12321；45254 反转仍 45254。复杂度 O(log10(x))（位数次循环）、O(1) 空间。边界：0 与单个数字都是回文（一位数反转相等）；用 long 保存反转结果可避免反转过程中的溢出（进阶做法是只反转后半部分再比较）。易错点：漏负数处理；用 int 且不做溢出考虑；忘记「不能用字符串库函数」的限制。",
          "完整程序如下（数字反转法，不使用字符串库函数）：\n```c\n#include <stdio.h>\n\n/* 判断是否为回文数（对称数）：反转数字与原数比较；负数不是回文数 */\nint is_palindrome(long x)\n{\n    long orig, rev = 0;\n    if (x < 0) return 0;               /* 负数（含负号）不是回文数 */\n    orig = x;\n    while (x) {\n        rev = rev * 10 + x % 10;       /* 逐位反转 */\n        x /= 10;\n    }\n    return rev == orig;                /* 反转后相等即为回文 */\n}\n\nint main(void)\n{\n    long n;\n    printf(\"请输入一个整数: \");\n    if (scanf(\"%ld\", &n) != 1) return 1;\n    printf(\"%s\\n\", is_palindrome(n) ? \"是对称数\" : \"不是对称数\");\n    return 0;\n}\n```\n示例：3、121、12321、45254 返回「是对称数」；-121、123 返回「不是对称数」。要点：O(位数) 时间、O(1) 空间；负数单独约定。"),
    430: ("思路：每两个字符拼成一个字节，高位在前：byte = (hex_val(第一个字符) << 4) | hex_val(第二个字符)。①字符转数值：'0'~'9' 减 '0'；'a'~'f' 减 'a' 加 10；'A'~'F' 减 'A' 加 10；非法字符返回 -1；②「1234」得到 0x12、0x34，即两字符一字节、顺序按原串；③输出循环逐字节打印；④奇数长度时最后一个字符没有配对，按规则停止（只导出完整字节）。复杂度 O(n)。易错点：高低半字节拼反（应 hi<<4 | lo）；十六进制字母大小写分支漏一个；非法字符不处理；输出格式写法。",
          "完整程序如下（每两字符拼一字节，高位在前）：\n```c\n#include <stdio.h>\n\n/* 单字符转数值：'0'~'9'/'a'~'f'/'A'~'F' -> 0~15；非法返回 -1 */\nint hex_val(char c)\n{\n    if (c >= '0' && c <= '9') return c - '0';\n    if (c >= 'a' && c <= 'f') return c - 'a' + 10;\n    if (c >= 'A' && c <= 'F') return c - 'A' + 10;\n    return -1;\n}\n\n/* 每两个字符拼成一个字节（高半字节在前）；返回转换出的字节数 */\nint str_to_hex(const char *s, unsigned char *out, int max)\n{\n    int n = 0;\n    while (s[0] && s[1] && n < max) {\n        int hi = hex_val(s[0]), lo = hex_val(s[1]);\n        if (hi < 0 || lo < 0) break;        /* 遇到非法字符：停止 */\n        out[n++] = (unsigned char)((hi << 4) | lo);\n        s += 2;\n    }\n    return n;\n}\n\nint main(void)\n{\n    char buf[256];\n    unsigned char out[128];\n    int n, i;\n    printf(\"请输入 0-9/a-f/A-F 组成的字符串: \");\n    if (scanf(\"%255s\", buf) != 1) return 1;\n    n = str_to_hex(buf, out, (int)sizeof(out));\n    printf(\"共导出 %d 个字节: \", n);\n    for (i = 0; i < n; i++) printf(\"0x%02X \", out[i]);\n    printf(\"\\n\");\n    return 0;\n}\n```\n示例：\"1234\" -> 0x12, 0x34。要点：两两成组、高半字节在前；非法字符与奇数尾字符按停止处理。"),
    431: ("位操作原理：x >> 8 把高 8 位移到低 8 位（低 8 位变 0）；x << 8 把低 8 位移到高 8 位；两者按位或合并后强转 uint16_t 截断（x<<8 在整型提升后可能占 16 位以上，截断只留低 16 位正好是交换结果）。物理含义：小端机器上 uint16 在内存中低字节在前，交换后 0x1234 与 0x3412 互换。替代实现：①联合体 union 交换字节；②htons/ntohs（网络字节序转换）；③__builtin_bswap16（GCC 内建）。复杂度 O(1)。易错点：漏强转导致高字节脏数据；移位与掩码顺序写错；混淆「字节交换」与「位反转」。",
          "完整程序如下：\n```c\n#include <stdio.h>\n#include <stdint.h>\n\n/* 16 位无符号数高低字节交换：0x1234 -> 0x3412 */\nuint16_t swap_bytes(uint16_t x)\n{\n    return (uint16_t)((x >> 8) | (x << 8));\n}\n\nint main(void)\n{\n    uint16_t v = 0x1234;\n    printf(\"0x%04X -> 0x%04X\\n\", v, swap_bytes(v));   /* 0x1234 -> 0x3412 */\n    return 0;\n}\n```\n要点：(x>>8) 移高字节到低位、(x<<8) 移低字节到高位，或运算合并后截断；O(1) 时间、O(1) 空间；也可用联合体或 __builtin_bswap16 实现。"),
    432: ("要点：①寄存器地址 0x40021000 用 volatile 指针宏访问——volatile 保证每次读写都真实发生、不被编译器优化掉；②「第 3 位 LED」对应 bit3，掩码 1u << 3（=0x08）；③用异或 ^= 翻转该位：0^x=x、1^x=~x——其它位与 0 异或保持不变，只有 bit3 每次翻转；④循环里「翻转 + 延时」交替亮灭即闪烁（题目说忽略延时函数，只需体现调用）；⑤不能直接赋值 LED_REG = (1u<<3)（其余位会被清零、其它 LED 全灭）；|= 只能常亮、&= ~ 只能常灭，都做不到交替闪烁。复杂度每轮 O(1)。易错点：忘记 volatile；直接赋值清掉其它位；用 |= 或 &=~ 代替 ^=。",
          "完整程序（bit3 对应掩码 1u << 3，异或翻转实现闪烁）：\n```c\n#include <stdint.h>\n\n#define LED_REG (*(volatile uint32_t *)0x40021000)   /* 32 位 LED 控制寄存器 */\n\nvoid delay(void);    /* 延时函数（题目说明可忽略其实现） */\n\nint main(void)\n{\n    while (1)\n    {\n        LED_REG ^= (1u << 3);    /* 异或翻转 bit3：仅第 3 位 LED 状态取反 */\n        delay();                 /* 延时：控制闪烁频率 */\n    }\n    return 0;\n}\n```\n要点：volatile 宏访问寄存器；^= (1u<<3) 只翻转 bit3、其余位不变；翻转+延时交替形成闪烁。"),
    433: ("位反转的逐位构造法：结果 r 初始 0，循环 16 次——①把 x 的最低位取出（x & 1）；②r 先左移一位再与它相或（r<<1 | 该位）——效果是先取出的位最终排在最左；③x 右移一位。16 次后 r 即 x 的位序完全颠倒（0x1234 变 0x2C48）。正确性验证：0x1234 = 0001 0010 0011 0100，反转 = 0010 1100 0100 1000 = 0x2C48。复杂度 O(16)=O(1)。优化：查表法——预先把 256 个字节值的倒序表做好，取高字节查表放低位、取低字节查表放高位两步拼装。易错点：漏掉 (uint16_t) 强转（r<<1 被整型提升、高位脏数据）；循环次数写成 8；移位方向搞反；与「高低字节交换」混淆。",
          "完整程序如下：\n```c\n#include <stdio.h>\n#include <stdint.h>\n\n/* 16 位无符号数位反转（位序颠倒）：0x1234 -> 0x2C48 */\nuint16_t reverse_bits(uint16_t x)\n{\n    uint16_t r = 0;\n    for (int i = 0; i < 16; i++) {\n        r = (uint16_t)((r << 1) | (x & 1));   /* 取 x 最低位拼到 r 末尾 */\n        x >>= 1;                              /* x 右移，处理下一位 */\n    }\n    return r;\n}\n\nint main(void)\n{\n    uint16_t v = 0x1234;\n    printf(\"0x%04X -> 0x%04X\\n\", v, reverse_bits(v));   /* 0x1234 -> 0x2C48 */\n    return 0;\n}\n```\n要点：16 次「取最低位→r 左移并入→x 右移」；O(16) 即 O(1)；大数据量可用 256 字节倒序查表加速。"),
    434: ("奇偶校验：统计 8 位中 1 的个数，返回其对 2 取余（奇数个 1 返回 1、偶数个返回 0）。逐位统计法：cnt += x & 1; x >>= 1; 循环到 x=0，最后 cnt & 1 取奇偶；x=0 时 0 个 1（偶数）正确返回 0。复杂度 O(8)=O(1)。更优实现：①Brian Kernighan 法 x &= x-1 每次消掉一个最低位的 1，循环次数等于 1 的个数；②异或折叠：连续三次 x ^= x>>4、x>>2、x>>1 把各位折叠到最低位，无需计数器；③CPU 内建 __builtin_parity。用途：UART 校验位、通信/内存检错——只能检出奇数个位错误。易错点：把「奇数返回 1」记反；对 0 的返回值写错；位宽理解错误。",
          "完整程序如下：\n```c\n#include <stdio.h>\n#include <stdint.h>\n\n/* 8 位奇偶校验：1 的个数为奇数返回 1，偶数返回 0 */\nint parity8(uint8_t x)\n{\n    int cnt = 0;\n    while (x) {\n        cnt += x & 1;        /* 统计当前最低位 */\n        x >>= 1;             /* 右移继续 */\n    }\n    return cnt & 1;          /* 个数对 2 取余：奇数为 1、偶数为 0 */\n}\n\nint main(void)\n{\n    printf(\"0x0F -> %d\\n\", parity8(0x0F));   /* 4 个 1：偶数，返回 0 */\n    printf(\"0x07 -> %d\\n\", parity8(0x07));   /* 3 个 1：奇数，返回 1 */\n    return 0;\n}\n```\n要点：逐位统计后取 mod 2；O(8) 即 O(1)；可用异或折叠或 __builtin_parity 优化。"),
}

